// Package db opens the Postgres connection pool and runs migrations.
//
// Layout of this directory:
//   - migrations/  goose migrations (SQL), embedded into the binary
//   - queries/     SQL queries that sqlc turns into Go code
//   - store/       the Go code generated by sqlc (do not edit by hand)
package db

import (
	"context"
	"embed"
	"fmt"
	"io/fs"
	"log/slog"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"
)

// migrationsFS holds the migration files inside the compiled binary, so the
// Docker image needs no extra files to migrate the database.
//
//go:embed migrations/*.sql
var migrationsFS embed.FS

// Connect opens a connection pool and checks that the database answers.
func Connect(ctx context.Context, databaseURL string) (*pgxpool.Pool, error) {
	pool, err := pgxpool.New(ctx, databaseURL)
	if err != nil {
		return nil, fmt.Errorf("creating connection pool: %w", err)
	}
	// pgxpool.New connects lazily, so ping once to fail fast on a bad URL.
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("connecting to database: %w", err)
	}
	return pool, nil
}

// Migrate applies all pending migrations. It is safe to run on every start:
// goose records applied versions in the goose_db_version table and skips them.
func Migrate(ctx context.Context, pool *pgxpool.Pool) error {
	migrations, err := fs.Sub(migrationsFS, "migrations")
	if err != nil {
		return err
	}

	// goose works with database/sql, so we wrap the pgx pool in a *sql.DB.
	// Closing this wrapper does not close the pool.
	sqlDB := stdlib.OpenDBFromPool(pool)
	defer sqlDB.Close()

	provider, err := goose.NewProvider(goose.DialectPostgres, sqlDB, migrations)
	if err != nil {
		return fmt.Errorf("creating migration provider: %w", err)
	}
	results, err := provider.Up(ctx)
	if err != nil {
		return fmt.Errorf("running migrations: %w", err)
	}
	for _, r := range results {
		slog.Info("applied migration", "version", r.Source.Version, "file", r.Source.Path, "duration", r.Duration)
	}
	return nil
}
